Lemma geo_1RB1LD_0LC0RB_1LD1RD_1LA1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_0LC0RB_1LD1RD_1LA1LD) = lift (Cc (Pos.succ p)).
Proof.
