(** The chain into this family lands on its anchor up to 1/1
    trailing blanks. *)
Lemma gbo_1RB1LD_0LC0RB_1LD1RD_1LA1LD : forall j, lift (cden [] [] j BB1_1RB1LD_0LC0RB_1LD1RD_1LA1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LD_0LC0RB_1LD1RD_1LA1LD = (StC, ((rep [S0;S0] j ++ [S0;S1;S1]) ++ [S0], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LD_0LC0RB_1LD1RD_1LA1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S0;S0] j ++ [S0;S1;S1], S0, []))).
  { unfold Cin_1RB1LD_0LC0RB_1LD1RD_1LA1LD. rewrite epow2_1RB1LD_0LC0RB_1LD1RD_1LA1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LD_0LC0RB_1LD1RD_1LA1LD. rewrite ?lift_app_blank. reflexivity.
