Definition mk_1RB1LD_1LC0RC_0LD1RB_1RC1LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LD_1LC0RC_0LD1RB_1RC1LA.

(** 1RB1LD_1LC0RC_0LD1RB_1RC1LA *)
Definition tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LD_1LC0RC_0LD1RB_1RC1LA : list Instr := [(StB, S0)].
Definition tmw_1RB1LD_1LC0RC_0LD1RB_1RC1LA : TM := tm_wrap_trs tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA pins_1RB1LD_1LC0RC_0LD1RB_1RC1LA.
Local Notation tm := tmw_1RB1LD_1LC0RC_0LD1RB_1RC1LA.

Definition Cc_1RB1LD_1LC0RC_0LD1RB_1RC1LA (p : positive) : cconf := (StD, (Ip p ++ [S0], S0, [])).
