Definition chn_1RB1LD_1LC0RC_0LD1RB_1RC1LA : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_1RB1LD_1LC0RC_0LD1RB_1RC1LA : srun tm false true chn_1RB1LD_1LC0RC_0LD1RB_1RC1LA AI0_1RB1LD_1LC0RC_0LD1RB_1RC1LA = Some (AI1_1RB1LD_1LC0RC_0LD1RB_1RC1LA, 4, 8).
