Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LD_1LC0RC_0LD1RB_1RC1LA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LD_1LC0RC_0LD1RB_1RC1LA : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1LD_1LC0RC_0LD1RB_1RC1LA : srun tm true true che_1RB1LD_1LC0RC_0LD1RB_1RC1LA BE0_1RB1LD_1LC0RC_0LD1RB_1RC1LA = Some (B1_1RB1LD_1LC0RC_0LD1RB_1RC1LA, 4, 10).
