  split; [lia|]. split; [| exact (gen_1RB1LD_1LC0RC_0LD1RB_1RC1LA v i q0 E)].
  rewrite (gsn_1RB1LD_1LC0RC_0LD1RB_1RC1LA v i q0 E).
  exact (srun_sound tm false true chn_1RB1LD_1LC0RC_0LD1RB_1RC1LA AI0_1RB1LD_1LC0RC_0LD1RB_1RC1LA AI1_1RB1LD_1LC0RC_0LD1RB_1RC1LA 4 8
