(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1LD_1LC0RC_0LD1RB_1RC1LA : forall j, lift (cden [] [] j BB1_1RB1LD_1LC0RC_0LD1RB_1RC1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LD_1LC0RC_0LD1RB_1RC1LA = (StD, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1LD_1LC0RC_0LD1RB_1RC1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1LD_1LC0RC_0LD1RB_1RC1LA. rewrite epow2_1RB1LD_1LC0RC_0LD1RB_1RC1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LD_1LC0RC_0LD1RB_1RC1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LD_1LC0RC_0LD1RB_1RC1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LD_1LC0RC_0LD1RB_1RC1LA.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LD_1LC0RC_0LD1RB_1RC1LA, cden, BE0_1RB1LD_1LC0RC_0LD1RB_1RC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LD_1LC0RC_0LD1RB_1RC1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB1LD_1LC0RC_0LD1RB_1RC1LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LD_1LC0RC_0LD1RB_1RC1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LD_1LC0RC_0LD1RB_1RC1LA p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_1RB1LD_1LC0RC_0LD1RB_1RC1LA).
    split; [lia|]. split; [| exact (gbo_1RB1LD_1LC0RC_0LD1RB_1RC1LA j)].
    rewrite (gso_1RB1LD_1LC0RC_0LD1RB_1RC1LA p j E).
    exact (srun_sound tm true true chb_1RB1LD_1LC0RC_0LD1RB_1RC1LA B0_1RB1LD_1LC0RC_0LD1RB_1RC1LA BB1_1RB1LD_1LC0RC_0LD1RB_1RC1LA 4 8
             run_boot_1RB1LD_1LC0RC_0LD1RB_1RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 10), (cden [] [] j B1_1RB1LD_1LC0RC_0LD1RB_1RC1LA).
    split; [| exact (geo_1RB1LD_1LC0RC_0LD1RB_1RC1LA p j E)].
    rewrite (gxi_1RB1LD_1LC0RC_0LD1RB_1RC1LA j).
    exact (srun_sound tm true true che_1RB1LD_1LC0RC_0LD1RB_1RC1LA BE0_1RB1LD_1LC0RC_0LD1RB_1RC1LA B1_1RB1LD_1LC0RC_0LD1RB_1RC1LA 4 10
             run_exit_1RB1LD_1LC0RC_0LD1RB_1RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LD_1LC0RC_0LD1RB_1RC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_1LC0RC_0LD1RB_1RC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LD_1LC0RC_0LD1RB_1RC1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_1LC0RC_0LD1RB_1RC1LA : stepn tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA 5 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LD_1LC0RC_0LD1RB_1RC1LA : existsb (fun tg => cfires tm_1RB1LD_1LC0RC_0LD1RB_1RC1LA c0 5 tg) pins_1RB1LD_1LC0RC_0LD1RB_1RC1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

