(** ** The lap *)

Lemma lap_1RB1LD_1LC1RD_0RD0LC_1RA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
