  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC1RD_0RD0LC_1RA1RC B0_1RB1LD_1LC1RD_0RD0LC_1RA1RC B1_1RB1LD_1LC1RD_0RD0LC_1RA1RC 6 12 p j' [] []).
